-- v1.2.x: the question generator version is fixed when a session is created (like `tuning`).
-- NULL = session created before v1.2.x → regenerated by the unchanged v1 generator (resume/scoring stay identical).
-- 2    = progressive-difficulty generator (generate-v2.ts).
ALTER TABLE game_sessions ADD COLUMN gen_version INTEGER;
-- Teacher preview sessions follow the same rule (they use the generator that students of this activity get).
ALTER TABLE teacher_preview_sessions ADD COLUMN gen_version INTEGER;
